import { useEffect, useState } from "react";
import axios from "axios";
import AdminPanel from "./components/AdminPanel";
import AuthPage from "./components/Authpage";

import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  BarElement,
  Title,
  Tooltip,
  Legend,
} from "chart.js";
import { Bar } from "react-chartjs-2";

ChartJS.register(
  CategoryScale,
  LinearScale,
  BarElement,
  Title,
  Tooltip,
  Legend
);

const API_URL = "http://localhost:5000";

function App() {
  const [candidates, setCandidates] = useState([]);
  const [darkMode, setDarkMode] = useState(false);
  const [showResults, setShowResults] = useState(false);
  const [electionClosed, setElectionClosed] = useState(false);
  const [selectedVotes, setSelectedVotes] = useState({});
  const [editId, setEditId] = useState(null);

  const [auth, setAuth] = useState({
    token: localStorage.getItem("token") || null,
    role: localStorage.getItem("role") || null,
  });

  const [candidateForm, setCandidateForm] = useState({
    firstName: "",
    lastName: "",
    candidacy: "",
    description: "",
    image: null,
  });

  const [message, setMessage] = useState("");

  // ================= FETCH =================
  const fetchCandidates = async () => {
    try {
      const res = await axios.get(`${API_URL}/api/candidates`);
      setCandidates(res.data);
    } catch {
      setMessage("Failed to load candidates.");
    }
  };

  useEffect(() => {
    fetchCandidates();
  }, []);

  const handleLogout = () => {
    localStorage.clear();
    setAuth({ token: null, role: null });
  };

  // ================= SAVE CANDIDATE =================
  const handleSaveCandidate = async () => {
    try {
      const formData = new FormData();
      formData.append("firstName", candidateForm.firstName);
      formData.append("lastName", candidateForm.lastName);
      formData.append("candidacy", candidateForm.candidacy);
      formData.append("description", candidateForm.description || "");
      if (candidateForm.image) formData.append("image", candidateForm.image);

      if (editId) {
        await axios.put(`${API_URL}/api/candidates/${editId}`, formData, {
          headers: { Authorization: `Bearer ${auth.token}` },
        });
        setMessage("Candidate updated.");
      } else {
        await axios.post(`${API_URL}/api/candidates`, formData, {
          headers: { Authorization: `Bearer ${auth.token}` },
        });
        setMessage("Candidate added.");
      }

      setCandidateForm({
        firstName: "",
        lastName: "",
        candidacy: "",
        description: "",
        image: null,
      });

      setEditId(null);
      fetchCandidates();
    } catch {
      setMessage("Failed to save candidate.");
    }
  };

  const handleDeleteCandidate = async (id) => {
    try {
      await axios.delete(`${API_URL}/api/candidates/${id}`, {
        headers: { Authorization: `Bearer ${auth.token}` },
      });
      fetchCandidates();
    } catch {
      setMessage("Delete failed.");
    }
  };

  // ================= VOTE =================
  const handleSelect = (position, candidateId) => {
    setSelectedVotes({
      ...selectedVotes,
      [position]: candidateId,
    });
  };

  const handleVoteCast = async () => {
    if (electionClosed) return;

    const confirmVote = window.confirm(
      "Are you sure you want to cast your vote?"
    );
    if (!confirmVote) return;

    try {
      for (let position in selectedVotes) {
        await axios.post(
          `${API_URL}/api/vote/${selectedVotes[position]}`,
          {},
          { headers: { Authorization: `Bearer ${auth.token}` } }
        );
      }

      setMessage("Vote successfully cast!");
      setSelectedVotes({});
      fetchCandidates();
    } catch {
      setMessage("Voting failed.");
    }
  };

  const groupedCandidates = candidates.reduce((acc, candidate) => {
    const key = candidate.candidacy || "Other";
    if (!acc[key]) acc[key] = [];
    acc[key].push(candidate);
    return acc;
  }, {});

  if (!auth.token) return <AuthPage setAuth={setAuth} />;

  return (
    <div
      style={{
        minHeight: "100vh",
        backgroundColor: darkMode ? "#7f1d1d" : "#dc2626",
        color: "white",
        padding: 20,
      }}
    >
      {/* HEADER */}
      <div style={{ display: "flex", justifyContent: "space-between" }}>
        <h1>🎓 SorSU Online Voting</h1>

        <div>
          <button onClick={() => setDarkMode(!darkMode)}>
            {darkMode ? "Light Mode" : "Dark Mode"}
          </button>

          <button onClick={handleLogout} style={{ marginLeft: 10 }}>
            Logout
          </button>
        </div>
      </div>

      {message && <p>{message}</p>}

      {/* ADMIN CONTROLS */}
      {auth.role === "admin" && (
        <div style={{ marginBottom: 20 }}>
          <button
            onClick={() => setElectionClosed(!electionClosed)}
            style={{ marginRight: 10 }}
          >
            {electionClosed ? "Open Election" : "Close Election"}
          </button>

          {electionClosed && (
            <button onClick={() => setShowResults(!showResults)}>
              {showResults ? "Hide Results" : "View Results"}
            </button>
          )}
        </div>
      )}

      {/* ADMIN PANEL */}
      {auth.role === "admin" && !showResults && (
        <AdminPanel
          candidateForm={candidateForm}
          setCandidateForm={setCandidateForm}
          onSave={handleSaveCandidate}
          editId={editId}
          setEditId={setEditId}
          onDelete={handleDeleteCandidate}
        />
      )}

      {/* RESULTS */}
      {showResults ? (
        <div>
          <h2>📊 Election Results</h2>

          {Object.entries(groupedCandidates).map(([position, list]) => {
            const sorted = [...list].sort(
              (a, b) => (b.votes || 0) - (a.votes || 0)
            );

            const data = {
              labels: sorted.map(
                (c) => `${c.firstName} ${c.lastName}`
              ),
              datasets: [
                {
                  label: `${position} Votes`,
                  data: sorted.map((c) => c.votes || 0),
                  backgroundColor: "white",
                },
              ],
            };

            return (
              <div key={position} style={{ marginBottom: 40 }}>
                <h3>{position}</h3>
                <Bar data={data} />
              </div>
            );
          })}
        </div>
      ) : (
        auth.role === "user" && !electionClosed && (
          <div>
            <h2>🗳 Cast Your Vote</h2>

            {Object.entries(groupedCandidates).map(([position, list]) => (
              <div key={position} style={{ marginBottom: 20 }}>
                <h3>{position}</h3>

                {list.map((c) => (
                  <div key={c._id}>
                    <label>
                      <input
                        type="radio"
                        name={position}
                        value={c._id}
                        checked={selectedVotes[position] === c._id}
                        onChange={() =>
                          handleSelect(position, c._id)
                        }
                      />
                      {c.firstName} {c.lastName}
                    </label>
                  </div>
                ))}
              </div>
            ))}

            <button
              onClick={handleVoteCast}
              style={{
                padding: "10px 20px",
                fontWeight: "bold",
                backgroundColor: "white",
                color: "red",
                border: "none",
                cursor: "pointer",
              }}
            >
              Vote Cast
            </button>
          </div>
        )
      )}
    </div>
  );
}

export default App;
